nextflow_process {

    name "Test Process MACSYFINDER_DOWNLOAD"
    script "../main.nf"
    process "MACSYFINDER_DOWNLOAD"
    tag "modules"
    tag "modules_nfcore"
    tag "macsyfinder"
    tag "macsyfinder/download"

    test("macsyfinder_download - TXSScan") {

        when {
            process {
                """
                input[0] = 'TXSScan'
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(
                    process.out.models.collect { file(it).name },
                    process.out.findAll { key, val -> key.startsWith("versions") }
                ).match() }
            )
        }
    }

    test("macsyfinder_download - TXSScan - stub") {

        options "-stub"

        when {
            process {
                """
                input[0] = 'TXSScan'
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(sanitizeOutput(process.out)).match() }
            )
        }
    }
}
